package youtube

import "regexp"

// validURLPatterns returns the _VALID_URL regexes for YoutubeIE.
//
// GOVS: ported verbatim from yt-dlp _video.py YoutubeIE._VALID_URL. RE2 has no
// negative lookahead or backreferences, so:
//   - (?!videoseries|live_stream) is enforced in YoutubeIE.Suitable;
//   - the Python conditional (?(1).+)? cannot be expressed: validURLPattern
//     requires the URL prefix and allows trailing content, while
//     validBareIDPattern matches a naked 11-character ID at end of string.
func validURLPatterns() []*regexp.Regexp {
	return []*regexp.Regexp{
		regexp.MustCompile(validURLPattern),
		regexp.MustCompile(validBareIDPattern),
	}
}

