// validBareIDPattern mirrors the naked-ID branch of yt-dlp's _VALID_URL. It is
// kept separate from validURLPattern because RE2 cannot express Python's
// conditional (?(1).+)?: the trailing content is only allowed when the URL
// prefix (group 1) matched. A naked ID must therefore be exactly 11 characters
// followed by '#' or the end of the string.
const validBareIDPattern = `^(?P<id>[0-9A-Za-z_-]{11})(?:\#|$)`

// reNonVideoPath matches embedded playlist/livestream paths that yt-dlp
// excludes via a negative lookahead after v/embed/e/shorts/live.
var reNonVideoPath = regexp.MustCompile(`(?:^|/)(?:v|embed|e|shorts|live)/(?:videoseries|live_stream)`)
